<?php
function handleAction():never{if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))reject('CSRF token không hợp lệ. Tải lại trang rồi thử lại.',419);$action=(string)($_POST['action']??'');$cid=(int)($_POST['course_id']??0);$stamp=['created_at'=>now(),'updated_at'=>now()];$handlers=['register'=>'auth_actions','login'=>'auth_actions','logout'=>'auth_actions','enroll'=>'student_actions','last_lesson'=>'student_actions','complete'=>'student_actions','submit_quiz'=>'student_actions','course_save'=>'instructor_actions','course_state'=>'instructor_actions','course_delete'=>'instructor_actions','chapter_save'=>'instructor_actions','chapter_delete'=>'instructor_actions','lesson_save'=>'instructor_actions','lesson_delete'=>'instructor_actions','quiz_save'=>'instructor_actions','user_status'=>'admin_actions','category_save'=>'admin_actions','category_delete'=>'admin_actions','ai'=>'ai_actions'];if(!isset($handlers[$action]))reject('Thao tác không tồn tại.',404);$handler=$handlers[$action];require_once __DIR__.'/'.$handler.'.php';$handler($action,$cid,$stamp);}
